  public static void InstallSavedReadablePresentation(){if(EditorApplication.isPlaying||EditorApplication.isCompiling)throw new InvalidOperationException("Stopped compiled Editor required.");for(int i=0;i<UnityEngine.SceneManagement.SceneManager.sceneCount;i++)if(UnityEngine.SceneManagement.SceneManager.GetSceneAt(i).isDirty)throw new InvalidOperationException("Preserve dirty scene before explicit Submarine presentation repair.");var scene=EditorSceneManager.OpenScene(ScenePath,OpenSceneMode.Single);InstallOpenReadablePresentation();if(!EditorSceneManager.SaveScene(scene))throw new System.IO.IOException("Could not save Submarine owned presentation repair.");AssetDatabase.SaveAssets();}
  public static void InstallOpenReadablePresentation(){var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(EditorApplication.isPlaying||EditorApplication.isCompiling||scene.path!=ScenePath)throw new InvalidOperationException("Exact stopped owned Submarine scene required.");var m=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<SubmarineMatch>(true)).Single();var rally=m.drivingViews.rally;if(rally.session!=m||rally.trucks.Length!=4||!rally.trucks.SequenceEqual(m.divers.Select(d=>d.truck)))throw new InvalidOperationException("Exact original full NWH roster required.");var expectedOffset=new Vector3(0,4.5f,-24);if(rally.groundOffset!=new Vector3(0,7,-17)&&rally.groundOffset!=expectedOffset||Mathf.Abs(rally.groundLookAhead-8)>.0001f&&Mathf.Abs(rally.groundLookAhead-2)>.0001f)throw new InvalidOperationException("Preserve customized chase settings.");var frame=m.broadcast.GetComponent<SportsBroadcastFraming>();if(frame==null||frame.session!=m||frame.cameraRig!=m.broadcast||!frame.trucks.SequenceEqual(rally.trucks)||frame.sharedDefaults==null||AssetDatabase.GetAssetPath(frame.sharedDefaults)!=Shared)throw new InvalidOperationException("Original common Cinemachine profile/roster required.");var config=JsonUtility.FromJson<SportsBroadcastSettings>(JsonUtility.ToJson(frame.sharedDefaults.settings));config.elevation=35;config.azimuth=-20;config.minimumTruckHeight=.12f;config.preferredTruckHeight=.18f;config.minimumDistanceInTruckLengths=1.2f;config.maximumDistanceInTruckLengths=2.2f;config.nearbyTruckLengths=1.5f;config.objectiveRangeInTruckLengths=3;config.primaryWeight=4;config.objectiveWeight=1;config.minimumShotSeconds=2;if(!frame.useSharedDefaults&&JsonUtility.ToJson(frame.settings)!=JsonUtility.ToJson(config))throw new InvalidOperationException("Preserve customized broadcast settings.");var cameras=rally.views.Select(v=>v.view).Concat(new[]{m.broadcast.view}).ToArray();var effects=cameras.Select(c=>c.GetComponent<BogCameraEffects>()).ToArray();if(effects.Length!=5||effects.Any(e=>e==null||e.course!=null||e.waterSurface==null||Mathf.Abs(e.densityScale-1)>.0001f&&Mathf.Abs(e.densityScale-.35f)>.0001f)||effects.Any(e=>e.waterSurface!=effects[0].waterSurface))throw new InvalidOperationException("Exact five original per-camera ocean bindings required; preserve custom density.");var water=effects[0].waterSurface.GetComponent<Renderer>().sharedMaterial;if(AssetDatabase.GetAssetPath(water)!=Ocean||!water.HasProperty("_Fog_Density")||Mathf.Abs(water.GetFloat("_Fog_Density")-.6f)>.0001f&&Mathf.Abs(water.GetFloat("_Fog_Density")-.12f)>.0001f)throw new InvalidOperationException("Preserve custom ocean material.");
   var presenter=m.menus.GetComponentsInChildren<SportsScorePresentation>(true).Single(p=>p.session==m);var accent=presenter.accent;var mask=presenter.notification.transform.Find("Mask Content")as RectTransform;if(presenter.name!="Submarine delivered points · existing Heat"||accent==null||accent.name!="Actual credited participant color"||mask==null||mask.GetComponent<CanvasGroup>()==null||accent.raycastTarget||accent.sprite!=null||accent.transform.parent!=presenter.notification.transform&&accent.transform.parent!=mask||accent.rectTransform.anchorMin!=Vector2.zero||accent.rectTransform.anchorMax!=new Vector2(1,0)||accent.rectTransform.offsetMin!=new Vector2(10,2)||accent.rectTransform.offsetMax!=new Vector2(-10,6))throw new InvalidOperationException("Preserve custom Submarine Heat accent bindings.");
   // All guards precede mutation. Cab transforms/lens/look remain untouched;
   // Follow(dt) has no airborne argument here and always uses this chase offset.
   if(accent.transform.parent!=mask){var rect=accent.rectTransform;rect.SetParent(mask,false);rect.anchorMin=Vector2.zero;rect.anchorMax=new Vector2(1,0);rect.offsetMin=new Vector2(10,2);rect.offsetMax=new Vector2(-10,6);EditorUtility.SetDirty(rect);}rally.groundOffset=expectedOffset;rally.groundLookAhead=2;frame.settings=config;frame.useSharedDefaults=false;foreach(var e in effects){e.densityScale=.35f;EditorUtility.SetDirty(e);}water.SetFloat("_Fog_Density",.12f);EditorUtility.SetDirty(water);EditorUtility.SetDirty(rally);EditorUtility.SetDirty(frame);EditorSceneManager.MarkSceneDirty(scene);Debug.Log("SUBMARINE_READABLE_PRESENTATION_AUTHORED existing chase lookahead2/offset(0,4.5,-24), local broadcast35degrees, per-camera density.35 and owned ocean fog.12. Original Bog default1, cabs, NWH, buoyancy, scoring and shared profiles unchanged; native/visual pending.");
  }
 }
